  });
});

corrected_code:
io.on('connection', (socket) => {
  socket.on('trading:cancel_order', async ({ orderId }) => {
    const order = await LimitOrder.findOne({ where: { id: orderId, traderId: socket.data.traderId } });
    if (!order) return socket.emit('order_cancel_failed', { reason: 'Order not found or not owned by trader' });
    order.status = 'CANCELED';
    await order.save();
    socket.emit('order_canceled_confirmed', { orderId: order.id, status: order.status });
  });
});
